/// <summary>
/// When selection changed for level Header/Line hide/show from and to date, purchase group and term effective date
/// </summary>
/// <returns>int</returns>
int selectionChange()
{
    int ret = next selectionChange();       

    METMarkupAutoSetupHelper markupAutoSetupHelper = METMarkupAutoSetupHelper::newFromFormRun(this.formRun());
    markupAutoSetupHelper.updateRebateControlsVisible(element.moduleType, element.moduleCategory);

    return ret;     
}
